buggy.reported_examples:
# Test precision of integer power operations
x = 94906267
try:
    result = x ** 2
    probe("x = 94906267, compute x ** 2", result)
except Exception as e:
    probe("x = 94906267, compute x ** 2", "__error__: " + type(e).__name__ + ": " + str(e))

# Also record the expected value
try:
    expected = 9007199515875289
    probe("expected:: x = 94906267, compute x ** 2", expected)
except Exception as e:
    probe("expected:: x = 94906267, compute x ** 2", "__error__: " + type(e).__name__ + ": " + str(e))

# Try to test with numba if available (as per the bug report mentioning njit)
try:
    from numba import njit

    @njit
    def pow2(x):
        return x ** 2

    x = 94906267
    compiled_result = pow2(x)
    probe("pow2 njit(94906267)", compiled_result)

    # Compare with pure Python version
    py_result = pow2.py_func(x)
    probe("pow2.py_func(94906267)", py_result)
except ImportError:
    probe("pow2 njit(94906267)", "__error__: ImportError: numba not available")
except Exception as e:
    probe("pow2 njit(94906267)", "__error__: " + type(e).__name__ + ": " + str(e))

